from typing import Any, Optional


class EnvCfgError(Exception):
    """Raised when a configuration problem is detected."""


def _coerce(value: Any, env_str: str) -> Any:
    """Coerce env_str to the type of value, raising EnvCfgError on failure."""
    if isinstance(value, str):
        return env_str
    if isinstance(value, bool):
        lower = env_str.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(f"Invalid value for '{env_str}': expected boolean, got '{env_str}'")
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            return float(env_str)
        except ValueError:
            raise EnvCfgError(f"Invalid value for '{env_str}': expected number, got '{env_str}'")
    raise EnvCfgError(f"Unsupported type for '{env_str}': {type(value).__name__}")


