import os
import tempfile
import tomllib
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load_cfg


def make_cfg(
    defaults: dict,
    toml_path: str | None = None,
    env_prefix: str = "APP",
    env: dict[str, str] | None = None,
) -> dict:
    return load_cfg(defaults, toml_path, env_prefix, env)


def _write_toml(path: Path, data: dict) -> None:
    with open(path, "wb") as f:
        tomllib.dump(data, f)


def test_imports():
    assert EnvCfgError is not None
    assert load_cfg is not None


def test_defaults_only():
    cfg = make_cfg({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    defaults = {"port": 8080, "host": "localhost"}
    toml = {"port": 9000}
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        toml_path = f.name
    try:
        _write_toml(Path(toml_path), toml)
        cfg = make_cfg(defaults, toml_path)
        assert cfg == {"port": 9000, "host": "localhost"}
    finally:
        os.unlink(toml_path)


