    defaults = {"port": 8080, "host": "localhost"}
    toml = {"port": 9000}
    env = {"APP__PORT": "10000"}
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        toml_path = f.name
    try:
        _write_toml(Path(toml_path), toml)
        cfg = make_cfg(defaults, toml_path, env=env)
        assert cfg == {"port": 10000, "host": "localhost"}
    finally:
        os.unlink(toml_path)


